// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Font loaded at module level to guarantee render readiness
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type MegaphoneCounterProps = Record<string, any>;

const MegaphoneCounter: React.FC<MegaphoneCounterProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  mainCircleColor = "#f3f4f6",
  badgeBackgroundColor = "#ef4444",
  megaphoneColor = "#111827",
  badgeTextColor = "#ffffff",
  targetCount = 50000,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive baseline using canvas shortest dimension
  const size = Math.min(width, height);
  const baseCircleSize = size * 0.45;
  const iconSize = baseCircleSize * 0.65;

  // 1. Initial Circle Reveal
  const mainScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // 2. Badge Pop-in
  const badgeStartFrame = 15;
  const badgeScale = spring({
    frame: frame - badgeStartFrame,
    fps,
    config: { damping: 12, mass: 0.6, stiffness: 150 },
  });

  // 3. Counting Logic
  const countStartFrame = 25;
  const countDurationFrames = fps * durationInSeconds - countStartFrame - 30; // Finishes 1 second before end
  
  const currentCount = interpolate(
    frame,
    [countStartFrame, countStartFrame + countDurationFrames],
    [0, targetCount],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic), // Slows down as it approaches the target
    }
  );

  // Format the number with commas (e.g., 50,000)
  const displayCount = Math.floor(currentCount).toLocaleString('en-US');

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        alignItems: "center", 
        justifyContent: "center", 
        fontFamily: spaceGrotesk 
      }}
    >
      <div
        style={{
          position: "relative",
          width: baseCircleSize,
          height: baseCircleSize,
          transform: `scale(${mainScale})`,
          transition: "none",
        }}
      >
        {/* Main Circle */}
        <div
          style={{
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            backgroundColor: mainCircleColor,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0 20px 40px rgba(0,0,0,0.08)",
            transition: "none",
          }}
        >
          {/* Megaphone Icon */}
          <div
            style={{
              transition: "none",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <svg
              width={iconSize}
              height={iconSize}
              viewBox="0 0 24 24"
              fill="none"
              stroke={megaphoneColor}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ transition: "none" }}
            >
              <path d="m3 11 18-5v12L3 14v-3z" />
              <path d="M11.6 16.8a3 3 0 1 1-5.8-1.6" />
            </svg>
          </div>
        </div>

        {/* 
            Notification Badge 
            Positioned exactly on the top-right perimeter of the main circle.
            Mathematical positioning: 45 degrees relative to center.
            Left: 50% + cos(45deg)*50% = 85.35%
            Top:  50% - sin(45deg)*50% = 14.65%
        */}
        <div
          style={{
            position: "absolute",
            top: "14.65%",
            left: "85.35%",
            transform: `translate(-50%, -50%) scale(${badgeScale})`,
            backgroundColor: badgeBackgroundColor,
            borderRadius: 9999, // Perfect pill shape
            padding: `${size * 0.015}px ${size * 0.03}px`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0 10px 25px rgba(0,0,0,0.15)",
            zIndex: 10,
            transition: "none",
            minWidth: size * 0.08, // Prevents badge from collapsing when showing just "0"
          }}
        >
          <span
            style={{
              color: badgeTextColor,
              fontSize: size * 0.05,
              fontWeight: 700,
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums", // Prevents horizontal jitter while numbers tick up
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {displayCount}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MegaphoneCounter;